export default function AdminGallery() {
  const upload = async (e) => {
    const form = new FormData();
    form.append("image", e.target.files[0]);

    await fetch("http://localhost:5001/admin/gallery", {
      method: "POST",
      headers: {
        Authorization: "Bearer " + localStorage.getItem("adminToken"),
      },
      body: form,
    });

    alert("Image uploaded");
  };

  return (
    <div className="border border-white/10 p-10 rounded-xl">
      <h2 className="text-2xl font-bold text-[#e9b21a] mb-6">
        Upload Gallery Image
      </h2>

      <input type="file" onChange={upload} className="text-white" />
    </div>
  );
}
